-- ============================================================================
-- pin_drop_central_pa_photos.sql -- 21 of Randy's Central PA photos as Pin
-- Drop questions (Nov 27 2026). Needs pin_drop_local.sql first.
--
-- A photo round shows only the photo; the reveal names it (name and town).
-- Photos live in public/pin-drop/central-pa/ and reach phones under a
-- disguised address, so a file name never gives the answer away.
-- Sideling Hill Tunnel is left out: it's west of the map's edge.
--
-- Coordinates: Claude's estimates (landmarks from memory; the rest from the
-- street addresses Randy gave, noted beside them). Close, not survey-exact:
-- check them on the map. Circles 0.3 mi for a building, bridge or stand,
-- 0.4 for a mall or Chickies Rock, 0.5 for Intercourse.
--
-- SAFE TO RE-RUN: each photo is added or updated by (kind, label).
-- ============================================================================


-- Check: Central PA places by kind (PLACE 21, PHOTO 21).
SELECT kind, COUNT(*) AS places FROM pin_drop_places WHERE map_key = 'CENTRAL_PA' AND active GROUP BY kind ORDER BY kind;
